package com.rpb.reservation.workforce.payroll.supplemental;

import static com.rpb.reservation.workforce.payroll.supplemental.SupplementalDtos.*;
import static com.rpb.reservation.workforce.payroll.supplemental.SupplementalMoney.*;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;
import com.rpb.reservation.workforce.statutory.settlement.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.math.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class SupplementalService {
 private com.rpb.reservation.workforce.leave.encashment.LeaveEncashmentBridge encashments;
 @org.springframework.beans.factory.annotation.Autowired public void encashments(com.rpb.reservation.workforce.leave.encashment.LeaveEncashmentBridge bridge){this.encashments=bridge;}
 private final WorkforceAccess gate;private final PayrollAccess access;private final SupplementalRepository repository;private final WorkforceEmployeeRepository employees;private final WorkforceAudit audit;private final JdbcTemplate jdbc;private final WorkforceJson json;private final Clock clock;
 public SupplementalService(WorkforceAccess gate,PayrollAccess access,SupplementalRepository repository,WorkforceEmployeeRepository employees,WorkforceAudit audit,JdbcTemplate jdbc,WorkforceJson json,Clock clock){this.gate=gate;this.access=access;this.repository=repository;this.employees=employees;this.audit=audit;this.jdbc=jdbc;this.json=json;this.clock=clock;}
 private void enter(CurrentActor a,UUID store,UUID company,UUID employee){access.enter(a,store,company);access.employee(a,company,employee);}
 private Batch batch(CurrentActor a,UUID store,UUID id){gate.enter(a,store);var b=repository.find(a.tenantId(),id).orElseThrow(WorkforceException::missing);enter(a,store,b.companyId(),b.employeeId());sourceAccess(a,store,b.companyId(),b.proposal().source());return b;}
 private void sourceAccess(CurrentActor a,UUID store,UUID company,Source source){if(source!=null&&source.batchId()!=null){if("segment".equals(source.kind())){var original=new com.rpb.reservation.workforce.payroll.segment.SegmentRepository(jdbc,json).find(a.tenantId(),source.batchId()).orElseThrow(WorkforceException::missing);if(!original.company().equals(company))throw WorkforceException.forbidden();access.enter(a,store,company,original.calculation().cumulative().lines().stream().flatMap(l->l.sources().stream()).map(PayrollDtos.SourceRef::storeId).distinct().toList());return;}var original=new PayrollRepository(jdbc,json).find(a.tenantId(),source.batchId()).orElseThrow(WorkforceException::missing);var stores=original.calculation().lines().stream().flatMap(l->l.sources().stream()).map(PayrollDtos.SourceRef::storeId).distinct().toList();access.enter(a,store,company,stores);}}
 public SourcePage source(CurrentActor a,UUID store,UUID company,UUID employee,String month){enter(a,store,company,employee);var result=new SupplementalSourceResolver(jdbc,json,clock).source(a.tenantId(),company,employee,PayrollProfileValidation.month(month));sourceAccess(a,store,company,result.source());return result;}
 public List<Batch> list(CurrentActor a,UUID store,UUID company){access.enter(a,store,company);return repository.list(a.tenantId(),company).stream().peek(b->batch(a,store,b.id())).toList();}
 public MonthlySummary monthSummary(CurrentActor a,UUID store,UUID company,String value){
  access.enter(a,store,company);var month=PayrollProfileValidation.month(value);var ordinary=new PayrollRepository(jdbc,json).forMonth(a.tenantId(),company,month).orElse(null);
  boolean available=ordinary!=null&&Set.of("confirmed","published").contains(ordinary.status())&&ordinary.calculation()!=null;
  var people=new HashSet<UUID>();String gross=null,net=null;
  if(ordinary!=null&&ordinary.calculation()!=null)access.enter(a,store,company,ordinary.calculation().lines().stream().flatMap(l->l.sources().stream()).map(PayrollDtos.SourceRef::storeId).distinct().toList());
  if(available){gross=ordinary.calculation().totalGross();net=ordinary.calculation().totalNet();ordinary.calculation().lines().forEach(l->people.add(l.employeeId()));}
  var segmentRows=new com.rpb.reservation.workforce.payroll.segment.SegmentRepository(jdbc,json).formal(a.tenantId(),company,month);
  if(!segmentRows.isEmpty()&&!available&&new com.rpb.reservation.workforce.payroll.PayrollRepository(jdbc,json).employeeIds(a.tenantId(),company,month).stream().allMatch(id->segmentRows.stream().anyMatch(s->s.employee().equals(id)))){available=true;gross="0.00";net="0.00";}
  var segments=new ArrayList<com.rpb.reservation.workforce.payroll.PayrollBoardDtos.SegmentSummary>();for(var s:segmentRows){access.enter(a,store,company,s.calculation().cumulative().lines().stream().flatMap(l->l.sources().stream()).map(PayrollDtos.SourceRef::storeId).toList());people.add(s.employee());if(available){gross=add(gross,s.calculation().delta().gross());net=add(net,s.calculation().delta().net());}segments.add(new com.rpb.reservation.workforce.payroll.PayrollBoardDtos.SegmentSummary(s.id(),s.employee(),s.calculation().cumulative().lines().getFirst().employeeName(),s.from(),s.cutoff(),s.status(),s.calculation().delta().gross(),s.calculation().delta().net(),false));}
  var authorisedSources=new HashSet<UUID>();var records=new ArrayList<MonthlyRecord>();String extraGross="0.00",extraNet="0.00";
  for(var b:repository.forMonth(a.tenantId(),company,month)){
   if(b.proposal().source().batchId()!=null&&authorisedSources.add(b.proposal().source().batchId()))sourceAccess(a,store,company,b.proposal().source());people.add(b.employeeId());var c=b.calculation();
   extraGross=add(extraGross,c==null?null:c.grossDelta());extraNet=add(extraNet,c==null?null:c.employeeCashPayable());
   records.add(new MonthlyRecord(b.id(),b.employeeId(),b.employeeName(),b.originMonth(),b.settlementMonth(),b.status(),b.proposal().source().batchId(),c==null?null:c.grossDelta(),c==null?null:c.employeeCpfDeduction(),c==null?null:c.cdacDeduction(),c==null?null:c.employeeCashPayable(),c==null?null:c.employerCpfDelta(),c==null?null:c.sdlDelta()));
  }
  return new MonthlySummary(company,month.toString(),clock.instant(),available,people.size(),gross,net,extraGross,extraNet,available?add(gross,extraGross):null,available?add(net,extraNet):null,List.copyOf(records),List.copyOf(segments));
 }
 public Detail detail(CurrentActor a,UUID store,UUID id){return view(a,store,batch(a,store,id));}
 private Detail view(CurrentActor a,UUID store,Batch b){var payments=repository.payments(a.tenantId(),b.id());var paid=paid(payments);String remaining=b.calculation()==null?null:difference(b.calculation().employeeCashPayable(),money(paid));boolean changed=false;if(b.status().equals("calculated"))try{changed=!b.calculation().sourceFingerprint().equals(new SupplementalCalculation(jdbc,json,clock).calculate(a.tenantId(),b).sourceFingerprint());}catch(WorkforceException e){changed=true;}return new Detail(b,changed,payments,money(paid),remaining);}
 @Transactional public Detail save(CurrentActor a,UUID store,UUID id,Write c){
  if(id==null||c==null||c.commandId()==null||c.expectedVersion()==null||c.expectedVersion()!=0||c.companyId()==null||c.employeeId()==null||c.requestId()==null||c.revision()==null||c.hash()==null||c.proposalId()==null)throw WorkforceException.invalid();enter(a,store,c.companyId(),c.employeeId());repository.lock(a.tenantId(),id);new PayrollRepository(jdbc,json).lockSources(a.tenantId());repository.commandLock(c.commandId());var replay=repository.replay(a,store,id,c.commandId(),"create",c,Detail.class);if(replay.isPresent())return replay.get();if(repository.find(a.tenantId(),id).isPresent())throw WorkforceException.conflict();
  var approved=repository.approved(a.tenantId(),c.companyId(),c.employeeId(),c.requestId(),c.revision(),c.hash(),c.proposalId());if(repository.hasProposal(a.tenantId(),c.companyId(),c.requestId(),c.revision(),c.proposalId()))throw WorkforceException.conflict();var p=approved.proposal();sourceAccess(a,store,c.companyId(),p.source());new SupplementalSourceResolver(jdbc,json,clock).validate(a.tenantId(),c.companyId(),c.employeeId(),p);var employee=employees.find(a.tenantId(),c.employeeId()).orElseThrow(WorkforceException::missing);
  var b=new Batch(id,c.companyId(),c.employeeId(),employee.name(),p.originMonth(),p.settlementMonth(),"draft",1,p,approved.proof(),null,clock.instant());repository.save(a,store,b);var result=view(a,store,b);repository.command(a,store,c.companyId(),id,c.commandId(),"create",c,result);audit.changed(a,store,"supplemental.create",id,null,b);return result;
 }
 @Transactional public Detail action(CurrentActor a,UUID store,UUID id,Action c){
  if(c==null||c.commandId()==null||c.expectedVersion()==null||!Set.of("calculate","confirm","publish","void").contains(Objects.toString(c.action(),"")))throw WorkforceException.invalid();gate.enter(a,store);repository.lock(a.tenantId(),id);var b=batch(a,store,id);new PayrollRepository(jdbc,json).lockSources(a.tenantId());repository.commandLock(c.commandId());var replay=repository.replay(a,store,id,c.commandId(),c.action(),c,Detail.class);if(replay.isPresent())return replay.get();if(b.version()!=c.expectedVersion())throw WorkforceException.conflict();var approved=repository.approved(a.tenantId(),b.companyId(),b.employeeId(),b.approval().requestId(),b.approval().revision(),b.approval().hash(),b.proposal().id());
  Snapshot calculation=b.calculation();String status;
  switch(c.action()){
   case "calculate"->{if(!Set.of("draft","calculated").contains(b.status()))throw WorkforceException.conflict();calculation=new SupplementalCalculation(jdbc,json,clock).calculate(a.tenantId(),b);status="calculated";}
   case "confirm"->{notSelf(a,b);if(!b.status().equals("calculated")||calculation==null)throw WorkforceException.conflict();var fresh=new SupplementalCalculation(jdbc,json,clock).calculate(a.tenantId(),b);if(!Objects.equals(c.expectedFingerprint(),calculation.sourceFingerprint())||!fresh.sourceFingerprint().equals(calculation.sourceFingerprint()))throw new WorkforceException("SUPPLEMENTAL_SOURCE_CHANGED",409);if(!fresh.issues().isEmpty()||fresh.employeeCashPayable()==null)throw new WorkforceException("STATUTORY_SETTLEMENT_BLOCKED",409);var today=LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));if(approved.effectiveDate().isAfter(today)||YearMonth.parse(b.settlementMonth()).isAfter(YearMonth.from(today))||b.proposal().items().stream().anyMatch(i->i.eventEvidence().contractualPayableDate().isAfter(today)))throw WorkforceException.conflict();if(encashments!=null)encashments.consume(a,b.companyId(),b.employeeId(),b.id(),"supplemental",b.proposal().items());repository.consume(a.tenantId(),b);recognise(a.tenantId(),b,calculation);status="confirmed";}
   case "publish"->{notSelf(a,b);if(!b.status().equals("confirmed"))throw WorkforceException.conflict();status="published";}
   case "void"->{if(!Set.of("draft","calculated").contains(b.status()))throw WorkforceException.conflict();status="voided";}
   default->throw WorkforceException.invalid();
  }
  var next=new Batch(b.id(),b.companyId(),b.employeeId(),b.employeeName(),b.originMonth(),b.settlementMonth(),status,b.version()+1,b.proposal(),b.approval(),calculation,b.createdAt());repository.save(a,store,next);var result=view(a,store,next);repository.command(a,store,b.companyId(),id,c.commandId(),c.action(),c,result);audit.changed(a,store,"supplemental."+c.action(),id,b,next);return result;
 }
 private void recognise(UUID tenant,Batch b,Snapshot s){var ledger=new SettlementRepository(jdbc,json);var settlement=YearMonth.parse(b.settlementMonth());for(var m:s.balances()){ledger.liability(tenant,b.companyId(),b.employeeId(),YearMonth.parse(m.month()),settlement,"cpf_employee",m.employeeCpf().liabilityDelta(),b.id(),null,"supplemental:"+b.id(),m);ledger.liability(tenant,b.companyId(),b.employeeId(),YearMonth.parse(m.month()),settlement,"cpf_employer",m.employerCpf().liabilityDelta(),b.id(),null,"supplemental:"+b.id(),m);}ledger.liability(tenant,b.companyId(),null,YearMonth.parse(b.originMonth()),settlement,"sdl",s.sdlDelta(),b.id(),null,"supplemental:"+b.id(),s);ledger.liability(tenant,b.companyId(),b.employeeId(),YearMonth.parse(b.originMonth()),settlement,"cdac",s.cdacDelta(),b.id(),null,"supplemental:"+b.id(),s);}
 private void notSelf(CurrentActor a,Batch b){if(a.actorId().equals(employees.find(a.tenantId(),b.employeeId()).orElseThrow(WorkforceException::missing).accountId()))throw WorkforceException.forbidden();}
 @Transactional public Detail payment(CurrentActor a,UUID store,UUID id,UUID payment,PayrollDtos.PaymentWrite c){
  gate.enter(a,store);repository.lock(a.tenantId(),id);var b=batch(a,store,id);new PayrollRepository(jdbc,json).lockSources(a.tenantId());notSelf(a,b);if(!b.status().equals("published")||payment==null||c==null||!b.employeeId().equals(c.employeeId())||c.paymentDate()==null||c.paymentDate().isAfter(LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore"))))||c.paymentDate().isBefore(YearMonth.parse(b.settlementMonth()).atDay(1))||!PaymentPreferences.method(c.method())||c.note()==null||c.note().isBlank()||c.note().length()>500||c.reference()==null||c.reference().length()>100||c.amount()==null||!c.amount().matches("[0-9]{1,8}(\\.[0-9]{1,2})?")||number(c.amount()).signum()<=0)throw WorkforceException.invalid();
  var payments=repository.payments(a.tenantId(),id);var old=payments.stream().filter(p->p.id().equals(payment)).findFirst().orElse(null);String amount=money(number(c.amount()));String bank=PaymentPreferences.bank(c.bank());if(old!=null){if(!old.employeeId().equals(c.employeeId())||!old.amount().equals(amount)||!old.paymentDate().equals(c.paymentDate())||!old.method().equals(c.method())||!old.reference().equals(c.reference())||!old.note().equals(c.note())||!Objects.equals(old.bank(),bank)||!Objects.equals(old.reversesId(),c.reversesId())||!old.actorId().equals(a.actorId()))throw WorkforceException.conflict();return view(a,store,b);}
  if(c.method().equals("bank")&&(bank.isBlank()||c.reference().isBlank())||c.method().equals("cash")&&!bank.isBlank())throw WorkforceException.invalid();
  if(c.reversesId()==null){if(paid(payments).add(number(amount)).compareTo(number(b.calculation().employeeCashPayable()))>0)throw new WorkforceException("WORKFORCE_PAYROLL_OVERPAYMENT",409);}else{var original=payments.stream().filter(p->p.id().equals(c.reversesId())).findFirst().orElseThrow(WorkforceException::missing);if(original.reversesId()!=null||payments.stream().anyMatch(p->original.id().equals(p.reversesId()))||!original.amount().equals(amount)||!original.method().equals(c.method())||!Objects.equals(original.bank(),bank)||c.paymentDate().isBefore(original.paymentDate()))throw WorkforceException.conflict();}
  var next=new PayrollDtos.Payment(payment,b.employeeId(),amount,c.paymentDate(),c.method(),c.reference(),c.note(),c.reversesId(),a.actorId(),clock.instant(),bank);repository.payment(a.tenantId(),b,next);audit.changed(a,store,"supplemental.payment",payment,null,next);return view(a,store,b);
 }
 private BigDecimal paid(List<PayrollDtos.Payment> payments){return payments.stream().map(p->number(p.amount()).multiply(BigDecimal.valueOf(p.reversesId()==null?1:-1))).reduce(BigDecimal.ZERO,BigDecimal::add);}
 public List<Payslip> mine(CurrentActor a,UUID store){gate.enter(a,store);var employee=jdbc.query("select id from workforce_employees where tenant_id=? and account_id=?",(r,n)->r.getObject(1,UUID.class),a.tenantId(),a.actorId());if(employee.isEmpty())return List.of();return jdbc.query("select snapshot from workforce_supplemental_batches where tenant_id=? and employee_id=? and status='published' order by settlement_month desc,id",(r,n)->slip(a.tenantId(),json.read(r.getString(1),Batch.class)),a.tenantId(),employee.getFirst());}
 public Payslip mine(CurrentActor a,UUID store,UUID id){return mine(a,store).stream().filter(p->p.batchId().equals(id)).findFirst().orElseThrow(WorkforceException::missing);}
 private Payslip slip(UUID tenant,Batch b){String company=jdbc.queryForObject("select display_name from operating_entities where tenant_id=? and id=?",String.class,tenant,b.companyId());var s=b.calculation();String paid=money(paid(repository.payments(tenant,b.id())));return new Payslip(b.id(),company,b.employeeName(),b.originMonth(),b.settlementMonth(),b.status(),s.grossDelta(),s.employeeCpfDeduction(),s.cdacDeduction(),s.employeeCashPayable(),paid,difference(s.employeeCashPayable(),paid),b.proposal().source().batchId(),b.proposal().items().stream().map(i->new PayslipItem(i.label(),i.amount(),i.eventEvidence().businessType(),i.eventEvidence().classification(),b.originMonth(),b.settlementMonth())).toList());}
}
